// Synthetic replica of expo-camera@16 sources (TSX). The published package ships
// the precompiled build/ output; this src mirrors it for fidelity. The native
// view manager and module are unavailable at build time, so the camera does not
// render and capability queries return inert results off-device.
import { requireNativeModule, requireNativeViewManager } from "expo-modules-core";

const CameraNativeView = requireNativeViewManager("ExpoCamera");
const CameraNativeModule = requireNativeModule("ExpoCamera") as {
  getAvailableCameraTypesAsync(): Promise<string[]>;
} | null;

export const EXPO_CAMERA_OK = "EXPO_CAMERA_OK";

export type CameraFacing = "front" | "back";

export function CameraView(props: { facing?: CameraFacing; children?: unknown }) {
  return <CameraNativeView facing={props.facing ?? "back"}>{props.children}</CameraNativeView>;
}

export async function getAvailableCameraTypesAsync(): Promise<string[]> {
  if (!CameraNativeModule) {
    return [];
  }
  return CameraNativeModule.getAvailableCameraTypesAsync();
}
